var n=`1245-curry-goat`;var t=`world-1245`;var a=`JM`;var r=`central-america-caribbean`;var o=4;var s=247;var g={en:`Curry Goat`,ua:`Карі з козлятини`};var d={en:`Curry Goat is a dish from Jamaica featuring goat shoulder, garlic, yellow onion, scotch bonnet pepper. This home-sized recipe records each ingredient at the step where it is used.`,ua:`Карі з козлятини, страва кухні країни Ямайка з такими основними складниками: козяча лопатка, часник, жовта цибуля, перець скотч-боннет. У домашньому рецепті кожний продукт прив’язаний до етапу його використання.`};var l=[{en:`Combine the seasoning ingredients and coat the main protein or vegetables. Rest covered in the refrigerator for about 90 minutes.`,ua:`Змішайте приправи й ретельно покрийте ними м’ясо або овочі. Маринуйте під накриттям у холодильнику приблизно 90 хвилин.`,t:[`marinating`],m:90,i:[[`goat-shoulder`,900,`g`],[`curry-powder`,35,`g`],[`ground-allspice`,4,`g`],[`garlic`,5,`clove`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 14 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 14 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:14,i:[[`yellow-onion`,190,`g`],[`scotch-bonnet-pepper`,1,`pcs`],[`canola-oil`,45,`ml`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 115 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 115 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:115,i:[[`water`,980,`ml`],[`thyme`,4,`sprig`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 25 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 25 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:25,i:[[`potato`,330,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`green-onion`,25,`g`]]}];var u={slug:n,id:t,country:`JM`,region:r,servings:4,minutes:247,title:g,text:d,steps:l};export{a as country,u as default,t as id,s as minutes,r as region,o as servings,n as slug,l as steps,d as text,g as title};